package main

import (
	"encoding/json"
	"fmt"
	"os"

	"github.com/hashicorp/terraform/parser/schema"
)

func main() {
	if len(os.Args) < 3 {
		fmt.Println("Usage: go run script.go <source_file> <struct_name>")
		os.Exit(1)
	}

	sourceFile := os.Args[1]
	structName := os.Args[2]

	var structDef map[string]interface{}

	// Read the JSON content from the source file
	file, err := os.Open(sourceFile)
	if err != nil {
		panic(err)
	}
	defer file.Close()

	data, err := json.MarshalIndent(structDef, "", "    ")
	if err != nil {
		panic(err)
	}

	// Parse the struct definition
	err = parser.ParseSchema(data, &schema.Schema{})
	if err != nil {
		panic(err)
	}

	// Output the generated Avro schema to a file
	outFile, err := os.Create(fmt.Sprintf("%s.avsc", structName))
	if err != nil {
		panic(err)
	}
	defer outFile.Close()

	json.NewEncoder(outFile).Encode(&schema.Schema{
		Struct:     true,
		SchemaSpec: schema.SchemaSpec{Type: schema.SchemaSpec_TYPE_OBJECT},
	})
}
```

### How to Use This Program:

1. Save the above code into a file named `script.go`.
2. Run the following command in your terminal:
   ```sh
   go run script.go /path/to/your/go/source/file.go YourStructName
   ```
   Replace `/path/to/your/go/source/file.go` with the path to your Go source file and `YourStructName` with the name of the struct you want to convert.

